34	struct MaterializeLocalTensor : OpRewritePattern<ascendc::LocalTensorAutoOp> {
35	    using OpRewritePattern::OpRewritePattern;
36	
37	    static ascendc::TPosition getPosition(ascendc::LocalTensorAutoOp op)
38	    {
39	        if (op.getOutput())
40	            return ascendc::TPosition::VECOUT;
41	        if (op.getInput())
42	            return ascendc::TPosition::VECIN;
43	        llvm_unreachable("position is undefined because tensor cannot be enqueued");
44	    }
45	
46	    LogicalResult matchAndRewrite(ascendc::LocalTensorAutoOp op, PatternRewriter& rewriter) const override
47	    {
48	        auto type = op.getType();
49	        auto loc = op.getLoc();
50	        ascir::ConstantOpBuilder consts(rewriter);
51	        Value length;
52	        if (type.hasStaticShape()) {
53	            length = consts.i64(type.getNumElements() * type.getElementTypeBitWidth() / CHAR_BIT);
54	        } else {
55	            assert(op->getNumOperands() != 0 && "must have operands for dynamic shape");
56	            length = consts.i64(type.getElementTypeBitWidth() / CHAR_BIT);
57	            for (auto dim : op.getDynamicShape()) {
58	                length = rewriter.create<arith::MulIOp>(loc, length, dim);
59	            }
60	        }
61	        Value pipe = rewriter.create<ascendc::PipeOp>(loc);
62	        if (!op.getInput() && !op.getOutput()) {
63	            auto bufferTy = ascendc::TBufType::get(op.getContext(), ascendc::TPosition::VECCALC);
64	            Value buffer = rewriter.create<ascendc::TBufOp>(loc, bufferTy);
65	            rewriter.create<ascendc::TPipeInitBufferOp>(loc, pipe, buffer, length);
66	            rewriter.replaceOpWithNewOp<ascendc::TBufGetTensorOp>(op, type, buffer);
67	            return success();
68	        }
69	        auto queueTy = ascendc::QueueType::get(op.getContext(), getPosition(op), 1);
70	        Value queue = rewriter.create<ascendc::QueueOp>(loc, queueTy);
71	        Value num = consts.i32(1);
72	        rewriter.create<ascendc::TPipeInitQueueOp>(loc, pipe, queue, num, length);
73	        auto allocOp = rewriter.replaceOpWithNewOp<ascendc::TQueBindAllocTensorOp>(op, type, queue);
74	        rewriter.setInsertionPoint(allocOp->getBlock()->getTerminator());
75	        rewriter.create<ascendc::TQueBindFreeTensorOp>(allocOp->getLoc(), queue, allocOp.getTensor());
76	        return success();
77	    }
78	};
