88	        RewritePatternSet patterns(context);
89	        patterns.add<MaterializeLocalTensor>(context);
90	        if (applyPatternsAndFoldGreedily(funcOp, std::move(patterns)).failed()) {
91	            signalPassFailure();
92	        }
93	    }
