                return
            new_shape = [_mat(dim, KnownTypes.int64).to_ir() for dim in shape]
            handle = global_builder.get_ir_builder().create_asc_LocalTensorAutoOp(
                ir.get_local_tensor_type(dtype.to_ir()), False, False, new_shape)
